function validate([coins]) {
  if (!Array.isArray(coins) || coins.length < 1 || coins.length > 40000) return 'coins needs 1 to 40000 values.';
  if (coins.some(v => !Number.isInteger(v) || v < 1 || v > 40000)) return 'Each coin is an integer from 1 to 40000.';
  return null;
}

