function getMaximumConsecutive(coins) {
  const total = coins.reduce((sum, c) => sum + c, 0);
  const possible = new Array(total + 2).fill(false);
  possible[0] = true;
  for (const c of coins) {
    for (let s = total; s >= c; s--) if (possible[s - c]) possible[s] = true;
  }
  let x = 0;
  while (possible[x]) x++;
  return x;
}

