function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    const mode = Math.floor(rand() * 3);
    const coins = [];
    for (let i = 0; i < n; i++) {
      if (mode === 0) coins.push(1 + Math.floor(Math.pow(rand(), 4) * 40000));
      else if (mode === 1) coins.push(i % 2 === 0 ? 1 + Math.floor(rand() * 50) : 30000 + Math.floor(rand() * 10001));
      else coins.push(rand() < 0.9 ? 1 + Math.floor(rand() * 200) : 1 + Math.floor(rand() * 40000));
    }
    return [coins];
  }
  const n = 1 + Math.floor(rand() * 8);
  const top = rand() < 0.5 ? 4 : 15;
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
